create table if not exists public.workforce_skills(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.master_tenants(id) on delete cascade,skill_key text not null,name text not null,description text,created_at timestamptz not null default now(),unique(tenant_id,skill_key));
create table if not exists public.workforce_employee_skills(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.master_tenants(id) on delete cascade,employee_id uuid not null references public.workforce_employees(id) on delete cascade,skill_id uuid not null references public.workforce_skills(id) on delete cascade,proficiency text not null default 'competent' check(proficiency in('basic','competent','advanced','expert')),verified_at timestamptz,expires_on date,created_at timestamptz not null default now(),unique(employee_id,skill_id));
create table if not exists public.workforce_qualifications(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.master_tenants(id) on delete cascade,qualification_key text not null,name text not null,issuing_body text,created_at timestamptz not null default now(),unique(tenant_id,qualification_key));
create table if not exists public.workforce_employee_qualifications(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.master_tenants(id) on delete cascade,employee_id uuid not null references public.workforce_employees(id) on delete cascade,qualification_id uuid not null references public.workforce_qualifications(id) on delete cascade,credential_number text,issued_on date,expires_on date,status text not null default 'active' check(status in('active','expired','revoked','pending')),created_at timestamptz not null default now(),unique(employee_id,qualification_id));
create table if not exists public.clinic_procedure_skill_requirements(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.master_tenants(id) on delete cascade,procedure_id uuid not null references public.clinic_procedures(id) on delete cascade,skill_id uuid not null references public.workforce_skills(id) on delete cascade,minimum_proficiency text not null default 'competent' check(minimum_proficiency in('basic','competent','advanced','expert')),created_at timestamptz not null default now(),unique(procedure_id,skill_id));
create table if not exists public.clinic_procedure_qualification_requirements(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.master_tenants(id) on delete cascade,procedure_id uuid not null references public.clinic_procedures(id) on delete cascade,qualification_id uuid not null references public.workforce_qualifications(id) on delete cascade,created_at timestamptz not null default now(),unique(procedure_id,qualification_id));
create index if not exists workforce_employee_skills_lookup on public.workforce_employee_skills(tenant_id,employee_id); create index if not exists workforce_employee_qualifications_lookup on public.workforce_employee_qualifications(tenant_id,employee_id,status); create index if not exists procedure_skill_requirements_lookup on public.clinic_procedure_skill_requirements(tenant_id,procedure_id); create index if not exists procedure_qualification_requirements_lookup on public.clinic_procedure_qualification_requirements(tenant_id,procedure_id);
alter table public.workforce_skills enable row level security; alter table public.workforce_employee_skills enable row level security; alter table public.workforce_qualifications enable row level security; alter table public.workforce_employee_qualifications enable row level security; alter table public.clinic_procedure_skill_requirements enable row level security; alter table public.clinic_procedure_qualification_requirements enable row level security;
create policy workforce_skills_access on public.workforce_skills for all to authenticated using(tenant_id=public.get_current_tenant_id() and (public.has_tenant_permission(tenant_id,'workforce:manage') or public.has_tenant_permission(tenant_id,'agenda:create'))) with check(tenant_id=public.get_current_tenant_id() and public.has_tenant_permission(tenant_id,'workforce:manage'));
create policy workforce_employee_skills_access on public.workforce_employee_skills for all to authenticated using(tenant_id=public.get_current_tenant_id() and (public.has_tenant_permission(tenant_id,'workforce:manage') or public.has_tenant_permission(tenant_id,'agenda:create'))) with check(tenant_id=public.get_current_tenant_id() and public.has_tenant_permission(tenant_id,'workforce:manage'));
create policy workforce_qualifications_access on public.workforce_qualifications for all to authenticated using(tenant_id=public.get_current_tenant_id() and (public.has_tenant_permission(tenant_id,'workforce:manage') or public.has_tenant_permission(tenant_id,'agenda:create'))) with check(tenant_id=public.get_current_tenant_id() and public.has_tenant_permission(tenant_id,'workforce:manage'));
create policy workforce_employee_qualifications_access on public.workforce_employee_qualifications for all to authenticated using(tenant_id=public.get_current_tenant_id() and (public.has_tenant_permission(tenant_id,'workforce:manage') or public.has_tenant_permission(tenant_id,'agenda:create'))) with check(tenant_id=public.get_current_tenant_id() and public.has_tenant_permission(tenant_id,'workforce:manage'));
create policy procedure_skill_requirements_access on public.clinic_procedure_skill_requirements for all to authenticated using(tenant_id=public.get_current_tenant_id() and (public.has_tenant_permission(tenant_id,'procedures:read') or public.has_tenant_permission(tenant_id,'procedures:update'))) with check(tenant_id=public.get_current_tenant_id() and public.has_tenant_permission(tenant_id,'procedures:update'));
create policy procedure_qualification_requirements_access on public.clinic_procedure_qualification_requirements for all to authenticated using(tenant_id=public.get_current_tenant_id() and (public.has_tenant_permission(tenant_id,'procedures:read') or public.has_tenant_permission(tenant_id,'procedures:update'))) with check(tenant_id=public.get_current_tenant_id() and public.has_tenant_permission(tenant_id,'procedures:update'));
grant select,insert,update,delete on public.workforce_skills,public.workforce_employee_skills,public.workforce_qualifications,public.workforce_employee_qualifications,public.clinic_procedure_skill_requirements,public.clinic_procedure_qualification_requirements to authenticated; grant all on public.workforce_skills,public.workforce_employee_skills,public.workforce_qualifications,public.workforce_employee_qualifications,public.clinic_procedure_skill_requirements,public.clinic_procedure_qualification_requirements to service_role;